'use client';

import { useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react';
import { springEasing } from '@/lib/spring';
import { ColorPicker, type ColorFormat, type ColorPickerLabels } from '@/components/ui/color-picker/color-picker';
import { COLOR_FORMATS, detectFormat, formatColor, oklchToRgb, parseColor, rgbToOklch } from '@/components/ui/color-picker/color';
import { morphClock } from '@/components/ui/color-picker/morph';
import './color-palette.css';

export interface ColorPaletteLabels {
  /** Name of the whole palette, e.g. "Brand palette". */
  readonly group: string;
  /** Name of a swatch before its value; `{n}` is its place and `{total}` the count: "Color 2 of 3". */
  readonly color: string;
  /** Name of the button that adds a color. */
  readonly add: string;
  /** Name of the pointer's remove button on a swatch. */
  readonly remove: string;
  /** Spoken once a color has been removed. */
  readonly removed: string;
  /** Labels of every swatch's picker; `open` is the swatch's name above and is ignored here. */
  readonly picker: Partial<ColorPickerLabels>;
}

export const DEFAULT_PALETTE_LABELS: ColorPaletteLabels = {
  group: 'Palette',
  color: 'Color {n} of {total}',
  add: 'Add color',
  remove: 'Remove color',
  removed: 'Color removed',
  picker: {},
};

export interface ColorPaletteProps {
  /** The colors (controlled): one to `max` strings in hex, rgb(), hsl() or oklch(). An empty array is one default color. */
  readonly colors?: readonly string[];
  /** The initial colors when the palette owns them (uncontrolled). */
  readonly defaultColors?: readonly string[];
  /** Called with every color in `format`, in the user's order, on any change, addition or removal. */
  readonly onChange?: (colors: string[]) => void;
  /** Most colors the palette holds; the add button is gone at this count. Defaults to 4. */
  readonly max?: number;
  /** The output format of every color (controlled); one for the whole palette. */
  readonly format?: ColorFormat;
  /** The initial format when the palette owns it; defaults to the first of `formats`. */
  readonly defaultFormat?: ColorFormat;
  readonly onFormatChange?: (format: ColorFormat) => void;
  /** The formats every picker's switch offers; a single entry hides the switch. */
  readonly formats?: readonly ColorFormat[];
  /** Shows the opacity slider in every picker; without it alpha is dropped. */
  readonly alpha?: boolean;
  /** Renders one hidden input per color under this name: `FormData.getAll(name)` gives the array. */
  readonly name?: string;
  readonly labels?: Partial<ColorPaletteLabels>;
  readonly className?: string;
}

const DEFAULT_COLOR = '#ffffff';
/** A new swatch grows in with a hint of overshoot; a removed one folds away without it. */
const GROW = springEasing({ stiffness: 380, damping: 26 });
const FOLD = springEasing({ stiffness: 420, damping: 42 });

/**
 * The color in `format`, alpha dropped unless the palette shows it. A string already in `format` is
 * kept as written, so a picker gets back exactly what it emitted (a round trip could move the last
 * digit and make it re-read the color); one that does not parse stays as it is.
 */
function reformat(color: string, format: ColorFormat, alpha: boolean): string {
  const rgba = parseColor(color);
  if (!rgba || (detectFormat(color) === format && (alpha || rgba.a >= 1))) return color;
  return formatColor(alpha ? rgba : { ...rgba, a: 1 }, format);
}

/** The next color: the last one turned by `turn` degrees of OKLCH hue; a grey has no hue to turn, so it steps in lightness. */
function nextColor(last: string, turn: number, format: ColorFormat, alpha: boolean): string {
  const oklch = rgbToOklch(parseColor(last) ?? { r: 1, g: 1, b: 1, a: 1 });
  const next = oklch.c < 0.02 ? { ...oklch, l: oklch.l > 0.6 ? oklch.l - 0.3 : oklch.l + 0.3 } : { ...oklch, h: (oklch.h + turn) % 360 };
  const rgba = oklchToRgb(next);
  return formatColor(alpha ? rgba : { ...rgba, a: 1 }, format);
}

/** Without the Web Animations API, under reduced motion or inside a `data-reduced-motion` ancestor nothing moves. */
const still = (element: Element) =>
  typeof (element as HTMLElement).animate !== 'function' || window.matchMedia?.('(prefers-reduced-motion: reduce)').matches === true || element.closest('[data-reduced-motion]') !== null;

/** The picker's own swatch inside a palette item: the roving stop of that color. */
const swatchOf = (item: Element | null | undefined) => item?.querySelector<HTMLButtonElement>(':scope > .color-picker > .color-picker-swatch') ?? null;

/** How far a swatch reaches into the row: its width and the gap after it. */
function reach(item: HTMLElement) {
  const row = item.parentElement;
  const gap = row ? parseFloat(getComputedStyle(row).columnGap) || 0 : 0;
  return item.offsetWidth + gap;
}

function play(element: Element, keyframes: PropertyIndexedKeyframes, timing: { duration: number; easing: string }) {
  const animation = element.animate(keyframes, { ...timing, fill: 'both' });
  animation.playbackRate = morphClock.rate;
  return animation;
}

interface Ghost {
  readonly key: number;
  readonly color: string;
  /** The place in the row it folds away from. */
  readonly index: number;
  /** Its trailing margin when it was removed, in px: a swatch removed while growing in folds from there. */
  readonly from: number;
}

/**
 * One to `max` swatches, each a `ColorPicker`, with an add button. One Tab stop for the whole row
 * (roving tabindex): ← and → move between the swatches and the add button, Home and End jump to the
 * ends, Enter or Space opens the picker, Delete or Backspace removes the color. The add button opens
 * the new color's picker at once; a removed color hands the focus to its neighbour and is announced.
 * Swatches grow in and fold away on springs, interruptibly; under reduced motion or inside a
 * `data-reduced-motion` ancestor they appear and go instantly. The pickers keep their own behaviour
 * and API; only one is open at a time because each closes when the press or focus leaves it.
 * Styles: color-palette.css, imported here (shadcn tokens: background, foreground, border, ring).
 */
export function ColorPalette({ colors, defaultColors, onChange, max = 4, format, defaultFormat, onFormatChange, formats = COLOR_FORMATS, alpha = false, name, labels: partial, className }: ColorPaletteProps) {
  const labels = { ...DEFAULT_PALETTE_LABELS, ...partial };
  const [ownFormat, setOwnFormat] = useState<ColorFormat>(() => defaultFormat ?? formats[0] ?? 'hex');
  const currentFormat = format ?? ownFormat;
  const [ownColors, setOwnColors] = useState<readonly string[]>(() => defaultColors ?? []);
  const given = colors ?? ownColors;
  const list = given.length > 0 ? given : [DEFAULT_COLOR];
  const shown = list.map((color) => reformat(color, currentFormat, alpha));
  const canAdd = list.length < max;

  // The latest list, so a second event in the same tick (the picker reports its format, then its value) builds on the first.
  const latest = useRef(list);
  latest.current = list;
  const latestFormat = useRef(currentFormat);
  latestFormat.current = currentFormat;
  // Stable keys by place: the palette moves them on add and remove, a change of length from outside appends or drops.
  const keys = useRef<number[]>([]);
  const counter = useRef(0);
  while (keys.current.length < list.length) keys.current.push(counter.current++);
  if (keys.current.length > list.length) keys.current = keys.current.slice(0, list.length);
  // Keys rendered before: only a swatch that arrives later grows in.
  const known = useRef<Set<number> | null>(null);
  const [active, setActive] = useState(0);
  const stops = list.length + (canAdd ? 1 : 0);
  const current = Math.min(active, stops - 1);
  const [ghosts, setGhosts] = useState<readonly Ghost[]>([]);
  const [announcement, setAnnouncement] = useState('');
  const row = useRef<HTMLDivElement>(null);
  const openKey = useRef<number | null>(null);
  const focusIndex = useRef<number | null>(null);

  const commit = (next: string[]) => {
    latest.current = next;
    if (colors === undefined) setOwnColors(next);
    onChange?.(next);
  };

  const change = (index: number, value: string) => {
    const base = latest.current.map((color) => reformat(color, latestFormat.current, alpha));
    if (base[index] === value) return;
    base[index] = value;
    commit(base);
  };

  const changeFormat = (next: ColorFormat) => {
    latestFormat.current = next;
    if (format === undefined) setOwnFormat(next);
    onFormatChange?.(next);
    commit(latest.current.map((color) => reformat(color, next, alpha)));
  };

  const add = () => {
    const base = latest.current;
    if (base.length >= max) return;
    const key = counter.current++;
    keys.current = [...keys.current, key];
    openKey.current = key;
    setActive(base.length);
    commit([...base.map((color) => reformat(color, latestFormat.current, alpha)), nextColor(base[base.length - 1] ?? DEFAULT_COLOR, 360 / Math.max(max, 2), latestFormat.current, alpha)]);
  };

  const remove = (index: number) => {
    const base = latest.current;
    if (base.length <= 1) return;
    const key = keys.current[index];
    const item = row.current?.querySelector<HTMLElement>(`[data-key="${key}"]`);
    if (key !== undefined && item && !still(item)) {
      setGhosts((previous) => [...previous, { key, color: shown[index] ?? DEFAULT_COLOR, index, from: parseFloat(getComputedStyle(item).marginInlineEnd) || 0 }]);
    }
    keys.current = keys.current.filter((_, place) => place !== index);
    const neighbour = Math.min(index, base.length - 2);
    focusIndex.current = neighbour;
    setActive(neighbour);
    setAnnouncement((previous) => (previous === labels.removed ? `${labels.removed} ` : labels.removed));
    commit(base.filter((_, place) => place !== index).map((color) => reformat(color, latestFormat.current, alpha)));
  };

  useLayoutEffect(() => {
    const root = row.current;
    if (!root) return;
    const items = Array.from(root.querySelectorAll<HTMLElement>(':scope > [data-key]:not([data-leaving])'));
    items.forEach((item, index) => swatchOf(item)?.setAttribute('tabindex', index === current ? '0' : '-1'));
    // Swatches that arrived after the first render grow in: the row makes room for them on a spring.
    const seen = known.current;
    known.current = new Set(keys.current);
    if (seen) {
      for (const item of items) {
        if (seen.has(Number(item.dataset.key)) || still(item)) continue;
        play(item, { marginInlineEnd: [`${-reach(item)}px`, '0px'] }, GROW);
        // A swatch whose picker opens at once grows under the panel; any other fades in.
        const swatch = swatchOf(item);
        if (swatch && Number(item.dataset.key) !== openKey.current) play(swatch, { opacity: [0, 1], scale: [0.6, 1] }, GROW);
      }
    }
    if (focusIndex.current !== null) {
      swatchOf(items[focusIndex.current])?.focus();
      focusIndex.current = null;
    }
    if (openKey.current !== null) {
      swatchOf(root.querySelector(`[data-key="${openKey.current}"]`))?.click();
      openKey.current = null;
    }
  });

  const fold = (ghost: Ghost) => (element: HTMLElement | null) => {
    if (!element || element.dataset.folding !== undefined) return;
    element.dataset.folding = '';
    const done = () => setGhosts((previous) => previous.filter((entry) => entry.key !== ghost.key));
    play(element, { marginInlineEnd: [`${ghost.from}px`, `${-reach(element)}px`] }, FOLD);
    const dot = element.firstElementChild;
    const fading = dot ? play(dot, { opacity: [1, 0], scale: [1, 0.6] }, FOLD) : null;
    if (fading) fading.finished.then(done, done);
    else done();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const target = event.target as HTMLElement;
    const items = Array.from(row.current?.querySelectorAll<HTMLElement>(':scope > [data-key]:not([data-leaving])') ?? []);
    const isAdd = target.classList.contains('color-palette-add');
    const index = isAdd ? list.length : items.findIndex((item) => swatchOf(item) === target);
    if (index < 0) return;
    let next: number;
    switch (event.key) {
      case 'ArrowLeft': next = Math.max(0, index - 1); break;
      case 'ArrowRight': next = Math.min(stops - 1, index + 1); break;
      case 'Home': next = 0; break;
      case 'End': next = stops - 1; break;
      case 'Delete':
      case 'Backspace':
        if (isAdd) return;
        event.preventDefault();
        remove(index);
        return;
      default: return;
    }
    event.preventDefault();
    setActive(next);
    (next === list.length ? row.current?.querySelector<HTMLElement>(':scope > .color-palette-add') : swatchOf(items[next]))?.focus();
  };

  const pickerLabels = labels.picker;
  const total = list.length;
  const cells = list.map((_, index) => {
    const key = keys.current[index] ?? index;
    const value = shown[index] ?? DEFAULT_COLOR;
    const label = `${labels.color.replace('{n}', String(index + 1)).replace('{total}', String(total))}, ${value}`;
    return (
      <div key={key} data-key={key} className="color-palette-item" onFocus={(event) => { if ((event.target as Element) === swatchOf(event.currentTarget)) setActive(index); }}>
        <ColorPicker color={value} onChange={(next) => change(index, next)} format={currentFormat} onFormatChange={changeFormat} formats={formats} alpha={alpha} labels={{ ...pickerLabels, open: label }} />
        {total > 1 ? (
          <button type="button" className="color-palette-remove" aria-label={labels.remove} tabIndex={-1} onClick={() => remove(index)}>
            <svg viewBox="0 0 12 12" width="10" height="10" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><path d="M3 3l6 6M9 3 3 9" /></svg>
          </button>
        ) : null}
      </div>
    );
  });
  // Removed swatches fold away where they stood, outside the roving order and the accessibility tree.
  for (const ghost of [...ghosts].sort((a, b) => b.index - a.index)) {
    cells.splice(Math.min(ghost.index, cells.length), 0, (
      <div key={`ghost-${ghost.key}`} ref={fold(ghost)} className="color-palette-item" data-leaving="" aria-hidden="true" inert>
        <span className="color-palette-ghost" style={{ background: ghost.color }} />
      </div>
    ));
  }

  return (
    <div ref={row} role="group" aria-label={labels.group} className={`color-palette${className ? ` ${className}` : ''}`} onKeyDown={onKeyDown}>
      {cells}
      {canAdd ? (
        <button type="button" className="color-palette-add" aria-label={labels.add} tabIndex={current === list.length ? 0 : -1} onFocus={() => setActive(list.length)} onClick={add}>
          <svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><path d="M8 3v10M3 8h10" /></svg>
        </button>
      ) : null}
      <span className="color-palette-sr-only" aria-live="polite">{announcement}</span>
      {name ? shown.map((value, index) => <input key={keys.current[index] ?? index} type="hidden" name={name} value={value} />) : null}
    </div>
  );
}

/* ColorPalette: a row of ColorPicker swatches with an add button (color-palette.tsx). shadcn tokens only. */
.color-palette { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem; }
.color-palette-item { position: relative; display: flex; flex: none; }
/* The buttons draw themselves: no user-agent border, padding or background (Tailwind's preflight is not assumed). */
.color-palette-add,
.color-palette-remove {
  margin: 0;
  padding: 0;
  border: 0;
  background: none;
  font: inherit;
  color: inherit;
  appearance: none;
  -webkit-appearance: none;
  cursor: pointer;
  outline: none;
}
.color-palette-add {
  display: grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  border-radius: 9999px;
  color: color-mix(in oklab, var(--foreground) 60%, transparent);
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--foreground) 16%, transparent);
  transition: color 160ms ease, background-color 160ms ease;
}
.color-palette-add:hover { color: var(--foreground); background: color-mix(in oklab, var(--foreground) 6%, transparent); }
.color-palette-add:focus-visible { box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--foreground) 16%, transparent), 0 0 0 3px color-mix(in oklab, var(--ring) 60%, transparent); }
/* The remove button sits on the swatch's top-right edge, shown on hover and focus. */
.color-palette-remove {
  position: absolute;
  z-index: 1;
  top: -0.3125rem;
  right: -0.3125rem;
  display: grid;
  place-items: center;
  width: 1rem;
  height: 1rem;
  border-radius: 9999px;
  color: var(--foreground);
  background: var(--background);
  box-shadow: 0 0 0 1px var(--border), 0 1px 2px rgb(0 0 0 / 0.12);
  opacity: 0;
  scale: 0.6;
  pointer-events: none;
  transition: opacity 140ms ease, scale 180ms cubic-bezier(0.2, 0.9, 0.3, 1.3);
}
/* 16 px to look at, 24 px to press (WCAG 2.5.8), never over the swatch's centre. */
.color-palette-remove::before { content: ''; position: absolute; inset: -0.25rem; border-radius: 9999px; }
.color-palette-item:hover > .color-palette-remove,
.color-palette-item:focus-within > .color-palette-remove { opacity: 1; scale: 1; pointer-events: auto; }
/* Touch screens have no hover: the remove buttons stay in view. Their target grows up, away from the
   swatch, and not over it: a tap on the swatch opens its picker and never removes the color. */
@media (hover: none) {
  .color-palette-remove { opacity: 1; scale: 1; pointer-events: auto; }
  .color-palette-remove::before { inset: -0.75rem -0.25rem -0.25rem; }
}
/* While the swatch's picker is open, the panel covers the swatch: the remove button steps aside. */
.color-palette-item:has(> .color-picker > [aria-expanded='true']) > .color-palette-remove { display: none; }
/* A closing panel lies over its neighbours and the add button: let presses through its shadow wrapper too. */
.color-palette .color-picker-shadow:has(> [data-phase='closing']) { pointer-events: none; }
/* Opening a swatch while its right-hand neighbour's panel still folds away: both wrappers sit at the
   picker's z-index 30 and the later one in the DOM would paint over the panel that is opening. */
.color-palette .color-picker-shadow:has(> [data-phase='open']) { z-index: 31; }
/* A removed swatch, folding away: a plain circle of its color. */
.color-palette-ghost {
  display: block;
  width: 2rem;
  height: 2rem;
  border-radius: 9999px;
  box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--foreground) 16%, transparent);
}
.color-palette-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .color-palette-add,
  .color-palette-remove { transition: none; }
}
[data-reduced-motion] .color-palette-add,
[data-reduced-motion] .color-palette-remove { transition: none; }

@media (forced-colors: active) {
  .color-palette-add,
  .color-palette-ghost { border: 1px solid CanvasText; }
  .color-palette-remove { border: 1px solid CanvasText; color: CanvasText; background: Canvas; forced-color-adjust: none; }
  .color-palette-add:focus-visible { outline: 2px solid Highlight; outline-offset: 2px; }
}

'use client';

import { useLayoutEffect, useRef, useState } from 'react';
import {
  colorTexts, commitNow, useAgentPort, useChangeAuthor, writeColor, type AgentChangeShape, type AgentConnectorShape, type AgentPortMethods,
  type AgentRunOutcomeShape, type AgentStepCallShape, type AgentStepCheckShape,
} from '@/components/ui/color-picker/color-picker-agent';
import { COLOR_FORMATS, detectFormat, formatColor, parseColor, type ColorFormat } from '@/components/ui/color-picker/color';
import type { ColorPaletteProps } from './color-palette';

// The Color palette's side of the agent bridge (@cloudlet/agent). The palette never imports this
// file, so a page that does not call the hook ships none of it. The protocol and the connection
// come from the Color picker's adapter, which the palette installs anyway.

/** The palette's verbs; `add` and `remove` come and go with the number of colors. */
export type ColorPaletteAction = 'set' | 'add' | 'remove';

/**
 * The palette's record in the agent snapshot: the whole palette, since `onChange` names no color.
 *
 * @experimental The protocol may change before the bridge reaches 1.0.
 */
export type ColorPaletteEntry = {
  /** The component's name in the bridge: `color-palette` unless the app named it. */
  readonly ref: string;
  readonly component: 'color-palette';
  /** `set` always; `add` below `max`; `remove` with more than one color. */
  readonly actions: readonly ColorPaletteAction[];
  /** How a person names the palette: the `label` option, else `labels.group`. */
  readonly label: string;
  /** The colors as the palette shows them (its hidden fields under `name`), written in `format`; colors are counted from 0. */
  readonly colors: readonly string[];
  /** Most colors the palette holds. */
  readonly max: number;
  readonly format: ColorFormat;
  readonly formats: readonly ColorFormat[];
  /** The palette keeps opacity; without it a color set by a step loses its alpha. */
  readonly alpha: boolean;
};

/** @experimental The protocol may change before the bridge reaches 1.0. */
export interface ColorPaletteAgentOptions {
  /** The palette's name in the bridge, `[a-z][a-z0-9-]*`; default `color-palette`. A second palette on one agent needs its own. */
  readonly name?: string;
  /** How the agent's messages name the palette; default the palette's `labels.group`, else "Palette". */
  readonly label?: string;
}

const freeze = Object.freeze;
const quote = JSON.stringify;
const EMPTY: readonly never[] = freeze([]);
const UNAVAILABLE: AgentRunOutcomeShape = freeze({ status: 'unavailable' });
/** The palette's one color for an empty array. */
const DEFAULT_COLOR = '#ffffff';
const DEFAULT_MAX = 4;

/** Messages of the palette's own refusals; the shared ones come from `colorTexts`. */
const texts = freeze({
  noColor: (index: number, label: string, count: number) =>
    `There is no color ${index} in ${quote(label)}: it has ${count === 1 ? 'only color 0' : `colors 0–${count - 1}`}.`,
  full: (label: string, count: number) => `${quote(label)} already holds ${count} colors, its most.`,
  last: (label: string) => `${quote(label)} holds only one color, its least. Set it instead.`,
  notSet: (wanted: string, index: number, label: string, shown: string) =>
    `The app did not take ${quote(wanted)}: color ${index} of ${quote(label)} is still ${quote(shown)}.`,
  notAdded: (wanted: string, label: string, count: number) =>
    `The app did not take ${quote(wanted)}: ${quote(label)} still holds ${count === 1 ? '1 color' : `${count} colors`}.`,
  notRemoved: (index: number, label: string, count: number) =>
    `The app did not remove color ${index}: ${quote(label)} still holds ${count} colors.`,
});

/**
 * The color as the palette shows it: in `format`, alpha dropped unless the palette keeps it; a
 * string already in `format` stays as written, one that does not parse stays as it is. The same
 * rule as the palette's own, so the record matches its swatches and hidden fields.
 */
function reformat(color: string, format: ColorFormat, alpha: boolean): string {
  const rgba = parseColor(color);
  if (!rgba || (detectFormat(color) === format && (alpha || rgba.a >= 1))) return color;
  return formatColor(alpha ? rgba : { ...rgba, a: 1 }, format);
}

const sameList = (a: readonly string[], b: readonly string[]) => a.length === b.length && a.every((item, index) => item === b[index]);
const isIndex = (value: unknown): value is number => typeof value === 'number' && Number.isInteger(value);

interface Committed {
  readonly entry: ColorPaletteEntry;
  readonly entries: readonly ColorPaletteEntry[];
  /** Hands a new array to whoever owns it, as the committed render's props say. */
  readonly write: (colors: string[]) => void;
}

/**
 * Connects a `ColorPalette` to the agent bridge through its props:
 *
 * ```tsx
 * const brand = useColorPaletteAgent(agent, { colors, onChange: setColors }, { name: 'brand', label: 'Brand palette' });
 * <ColorPalette {...brand} />
 * ```
 *
 * The palette appears in `agent.snapshot()` as one record (`ColorPaletteEntry`) and takes the steps
 * `set [number, color]`, `add [color]` and `remove [number]`, numbers counted from 0; each answers
 * with the colors after it. Each change of the colors reaches `agent.subscribe` under the key
 * `colors` with who started the change: `user` through the palette, `agent` through a step, `app`
 * when the app changed the prop itself. The author is shared by the color adapters on the same
 * agent: a palette or picker whose value changes in the same commit as the one a person or a step
 * changed names the same author, so components on one state of the app report one source. A value
 * the app passes on in a later commit (from an effect, after a server answers) is named by that
 * commit: the app's, unless a person or a step changed something in it too. A palette without
 * `colors` (or `format`) is uncontrolled: the hook holds the colors (or the format) and hands the
 * palette controlled props. With `agent` null or undefined
 * the props come back as they are and nothing connects; keep the same agent for the component's life.
 *
 * A step answers by what the palette shows once React has committed the app's update: the colors
 * that stood, or "The app did not take…" when nothing changed.
 *
 * @experimental The protocol may change before the bridge reaches 1.0.
 */
export function useColorPaletteAgent<Props extends ColorPaletteProps>(
  agent: AgentConnectorShape | null | undefined,
  props: Props,
  options: ColorPaletteAgentOptions = {},
): Props {
  const { colors, defaultColors, onChange, max = DEFAULT_MAX, format, defaultFormat, onFormatChange, formats = COLOR_FORMATS, alpha = false, labels } = props;
  // The palette's own defaults, so an uncontrolled palette shows the same once the hook controls it.
  const [ownColors, setOwnColors] = useState<readonly string[]>(() => defaultColors ?? []);
  const [ownFormat, setOwnFormat] = useState<ColorFormat>(() => defaultFormat ?? formats[0] ?? 'hex');
  const author = useChangeAuthor(agent);
  const committed = useRef<Committed | null>(null);

  const givenColors = colors ?? ownColors;
  const shownFormat = format ?? ownFormat;
  const name = options.name ?? 'color-palette';
  const label = options.label ?? labels?.group ?? 'Palette';
  const write = (next: string[]): void => {
    if (colors === undefined) setOwnColors(next);
    onChange?.(next);
  };

  const [methods] = useState((): AgentPortMethods => {
    type Plan =
      | { readonly ok: false; readonly message?: string }
      | { readonly ok: true; readonly state: Committed; readonly next: readonly string[] | null; readonly fail: (now: ColorPaletteEntry) => string };
    const plan = (step: AgentStepCallShape): Plan => {
      const state = committed.current;
      if (!state || step.ref !== state.entry.ref) return { ok: false };
      const { colors: list, format, alpha, label, max } = state.entry;
      const { action, args } = step;
      const color = (input: string): string | Plan => writeColor(input, format, alpha) ?? { ok: false, message: colorTexts.notColor(input, label) };
      const place = (index: number): Plan | null => (index >= 0 && index < list.length ? null : { ok: false, message: texts.noColor(index, label, list.length) });
      if (action === 'set') {
        const [index, input] = args;
        if (args.length !== 2 || !isIndex(index) || typeof input !== 'string') return { ok: false, message: colorTexts.takes(step, 'the number of a color and a color') };
        const missing = place(index);
        if (missing) return missing;
        const value = color(input);
        if (typeof value !== 'string') return value;
        const current = list[index] ?? '';
        // The same color, even written otherwise: nothing to hand the app.
        const same = value === current || writeColor(current, format, alpha) === value;
        return {
          ok: true, state, next: same ? null : list.map((item, at) => (at === index ? value : item)),
          fail: (now) => texts.notSet(value, index, now.label, now.colors[index] ?? ''),
        };
      }
      if (action === 'add') {
        const [input] = args;
        if (args.length !== 1 || typeof input !== 'string') return { ok: false, message: colorTexts.takes(step, 'a color') };
        if (list.length >= max) return { ok: false, message: texts.full(label, list.length) };
        const value = color(input);
        if (typeof value !== 'string') return value;
        return { ok: true, state, next: [...list, value], fail: (now) => texts.notAdded(value, now.label, now.colors.length) };
      }
      if (action === 'remove') {
        const [index] = args;
        if (args.length !== 1 || !isIndex(index)) return { ok: false, message: colorTexts.takes(step, 'the number of a color') };
        const missing = place(index);
        if (missing) return missing;
        if (list.length <= 1) return { ok: false, message: texts.last(label) };
        return { ok: true, state, next: list.filter((_, at) => at !== index), fail: (now) => texts.notRemoved(index, now.label, now.colors.length) };
      }
      return { ok: false };
    };
    return freeze({
      snapshot: () => committed.current?.entries ?? EMPTY,
      check(step: AgentStepCallShape): AgentStepCheckShape {
        const verdict = plan(step);
        if (!verdict.ok) return freeze(verdict.message === undefined ? { available: false as const } : { available: false as const, message: verdict.message });
        return freeze({ available: true as const, permission: 'allow' as const, names: freeze({ target: verdict.state.entry.label }) });
      },
      // Read again from the committed state: props may have changed while the step waited.
      run(step: AgentStepCallShape): AgentRunOutcomeShape {
        const verdict = plan(step);
        if (!verdict.ok) return verdict.message === undefined ? UNAVAILABLE : freeze({ status: 'unavailable', message: verdict.message });
        const previous = verdict.state.entry.colors;
        if (!verdict.next) return freeze({ status: 'done', result: previous });
        const next = [...verdict.next];
        commitNow(() => {
          author.mark('agent');
          verdict.state.write(next);
        });
        const now = committed.current;
        // The app unmounted the palette in answer to the change.
        if (!now) return freeze({ status: 'done', gone: true });
        return sameList(now.entry.colors, previous)
          ? freeze({ status: 'failed', message: verdict.fail(now.entry) })
          : freeze({ status: 'done', result: now.entry.colors });
      },
    });
  });

  // Reads this commit's props: the colors the palette shows now, the record and, if the colors
  // changed, who changed them. Never the latest props: a later render may not have committed yet.
  const commit = (): readonly AgentChangeShape[] | null => {
    if (!agent) {
      committed.current = null;
      author.settle();
      return null;
    }
    const list = givenColors.length > 0 ? givenColors : [DEFAULT_COLOR];
    const shown = list.map((color) => reformat(color, shownFormat, alpha));
    const actions: ColorPaletteAction[] = ['set'];
    if (shown.length < max) actions.push('add');
    if (shown.length > 1) actions.push('remove');
    const source = author.settle();
    const before = committed.current;
    const old = before?.entry;
    const entry: ColorPaletteEntry = old && old.ref === name && old.label === label && sameList(old.colors, shown) && sameList(old.actions, actions)
      && old.max === max && old.format === shownFormat && old.alpha === alpha && sameList(old.formats, formats)
      ? old
      : freeze({
        ref: name, component: 'color-palette', actions: freeze(actions), label, colors: old && sameList(old.colors, shown) ? old.colors : freeze(shown),
        max, format: shownFormat, formats: freeze([...formats]), alpha,
      });
    committed.current = { entry, entries: before && entry === old ? before.entries : freeze([entry]), write };
    // The first commit is announced by connecting.
    if (!old || entry === old) return null;
    if (entry.colors === old.colors) return EMPTY;
    return freeze([freeze({ ref: name, component: 'color-palette', label, key: 'colors', value: entry.colors, previous: old.colors, source })]);
  };

  useAgentPort(agent, name, methods, commit);
  // Unmounted (or, under StrictMode, about to mount again): a step in flight finds no palette.
  useLayoutEffect(() => () => { committed.current = null; }, []);

  if (!agent) return props;

  const handleChange = (next: string[]): void => {
    author.mark('user');
    write(next);
  };
  const handleFormatChange = (next: ColorFormat): void => {
    if (format === undefined) setOwnFormat(next);
    onFormatChange?.(next);
  };

  return { ...props, colors: givenColors, format: shownFormat, onChange: handleChange, onFormatChange: handleFormatChange };
}
